 private void choose(int request){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");if(request==1)i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,request);}
 private ListedFile importFile(Uri uri)throws Exception{
  check();String name="dosya";Cursor c=getContentResolver().query(uri,null,null,null,null);if(c!=null)try{if(c.moveToFirst()){int col=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(col>=0)name=c.getString(col);}}finally{c.close();}
  String suffix=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"bin";File file=File.createTempFile("selected-","."+suffix,getCacheDir());boolean success=false;try{InputStream input=getContentResolver().openInputStream(uri);try{OutputStream out=new FileOutputStream(file);try{byte[]buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){check();out.write(buffer,0,n);}}finally{out.close();}}finally{input.close();}
  ListedFile entry=classify(file,name,suffix);success=true;return entry;}finally{if(!success)file.delete();}
 }
 /** Second file (merge partner, audio to add, subtitle, original SRT) as the picker would set it. */
 void useOther(ListedFile f){other=f==null?null:f.file;otherExt=f==null?"":f.ext;otherInfo=f==null?null:f.info;otherDisplay=f==null?"":f.name;}
 /** File type detection shared by the file picker and the full self test. */
 ListedFile classify(File file,String name,String suffix)throws Exception{
  suffix=detectDocument(file,suffix);MediaEngine.Info found=null;if(!Arrays.asList("srt","pdf","txt","md","rtf","html","htm","docx","odt","odp","pptx","xlsx","epub","csv","tsv","rst","image").contains(suffix)){if(!ready)throw new IOException(t("Yerel motor henüz hazır değil.","Motora herêmî hîn ne amade ye."));found=probe(file);}return new ListedFile(file,name,suffix,found);
 }
 private List<Uri> treeFiles(Uri tree)throws Exception{return treeFilesFrom(tree,DocumentsContract.getTreeDocumentId(tree));}
 private List<Uri> treeFilesFrom(Uri tree,String rootId)throws Exception{List<Uri> result=new ArrayList<Uri>();ArrayDeque<String>queue=new ArrayDeque<String>();Set<String>seen=new HashSet<String>();queue.add(rootId);while(!queue.isEmpty()){check();String id=queue.removeFirst();if(!seen.add(id))continue;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,DocumentsContract.Document.COLUMN_DISPLAY_NAME);if(c!=null)try{while(c.moveToNext()){check();String child=c.getString(0);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(1)))queue.add(child);else result.add(DocumentsContract.buildDocumentUriUsingTree(tree,child));}}finally{c.close();}}return result;}
 private void importMany(final List<Uri>input,final Uri tree){busy=true;cancelled=false;controls();message(t("Klasör / dosyalar taranıyor…","Peldank / pel tên lêgerîn…"));new Thread(new Runnable(){public void run(){final List<ListedFile>found=new ArrayList<ListedFile>();int failures=0;try{List<Uri>uris=tree==null?input:treeFiles(tree);for(Uri uri:uris){check();try{found.add(importFile(uri));}catch(Exception error){if(cancelled)throw error;failures++;failure(error);}}}catch(Exception error){if(!cancelled)failure(error);}final int skipped=failures;runOnUiThread(new Runnable(){public void run(){int first=files.size();files.addAll(found);batchEnabled=true;busy=false;selectFile(found.isEmpty()?selectedIndex:first);message(t("Listeye eklendi: ","Li lîsteyê zêde bûn: ")+found.size()+t(" · Atlanan / hatalı: "," · Derbaskirî / çewt: ")+skipped);}});}}).start();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;final Uri uri=data.getData();if(request==4&&uri!=null){importMany(null,uri);return;}if(request==1&&data.getClipData()!=null){List<Uri>uris=new ArrayList<Uri>();for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());importMany(uris,null);return;}if(uri==null)return;if(request==3){try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));outputTree=uri;getPreferences(0).edit().putString("tree",uri.toString()).apply();build();}catch(Exception error){failure(error);}return;}
  final int which=request;busy=true;cancelled=false;controls();new Thread(new Runnable(){public void run(){try{final ListedFile entry=importFile(uri);runOnUiThread(new Runnable(){public void run(){if(which==1){files.add(entry);busy=false;selectFile(files.size()-1);}else{other=entry.file;otherDisplay=entry.name;otherExt=entry.ext;otherInfo=entry.info;busy=false;build();}}});}catch(Exception error){failure(error);finishBusy();}}}).start();
 }
 String detectDocument(File f,String fallback)throws Exception {
  FileInputStream in=new FileInputStream(f);byte[]head=new byte[4096];int n;try{n=in.read(head);}finally{in.close();}
  if(n>=5&&new String(head,0,5,"US-ASCII").equals("%PDF-"))return "pdf";
  if(n>=6&&(new String(head,0,6,"US-ASCII").equals("GIF87a")||new String(head,0,6,"US-ASCII").equals("GIF89a")))return "gif";
  android.graphics.BitmapFactory.Options imageBounds=new android.graphics.BitmapFactory.Options();imageBounds.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getAbsolutePath(),imageBounds);if(imageBounds.outWidth>0&&imageBounds.outHeight>0)return "image";
  if(n>=2&&head[0]=='P'&&head[1]=='K'){
   ZipFile zip=new ZipFile(f);try{
    if(zip.getEntry("word/document.xml")!=null)return "docx";
    if(zip.getEntry("ppt/presentation.xml")!=null)return "pptx";
    if(zip.getEntry("xl/workbook.xml")!=null)return "xlsx";
    if(zip.getEntry("content.xml")!=null){
     ZipEntry mime=zip.getEntry("mimetype");String type="";
     if(mime!=null){InputStream m=zip.getInputStream(mime);try{byte[] b=new byte[256];int count=m.read(b);if(count>0)type=new String(b,0,count,"US-ASCII").trim();}finally{m.close();}}
     if(type.equals("application/vnd.oasis.opendocument.presentation"))return "odp";
     if(type.equals("application/vnd.oasis.opendocument.spreadsheet"))throw new IOException(t("ODS elektronik tabloları henüz desteklenmiyor.","Tabloyên ODS hîn nayên piştgirîkirin."));
     return "odt";
    }
    if(zip.getEntry("META-INF/container.xml")!=null)return "epub";
   }finally{zip.close();}throw new IOException(t("Bu ZIP dosyası desteklenen bir belge değil.","Ev dosyeya ZIP ne belgeyeke piştgirîkirî ye."));
  }
  if(n>=2&&((head[0]==(byte)0xff&&head[1]==(byte)0xfe)||(head[0]==(byte)0xfe&&head[1]==(byte)0xff)))return "txt";
  for(int i=0;i<n;i++)if(head[i]==0)return "bin";
  String start=new String(head,0,Math.max(0,n),"UTF-8").trim();if(fallback.equals("srt")||start.matches("(?s).*\\d{2}:\\d{2}:\\d{2},\\d{3} --> .*"))return "srt";
  if(start.startsWith("{\\rtf"))return "rtf";
  if(start.toLowerCase(Locale.ROOT).contains("<html")||start.toLowerCase(Locale.ROOT).startsWith("<!doctype html"))return "html";
  if(Arrays.asList("txt","md","csv","tsv","rst","html","htm","rtf").contains(fallback))return fallback;
  try{java.nio.charset.CharsetDecoder decoder=java.nio.charset.Charset.forName("UTF-8").newDecoder();java.nio.charset.CoderResult result=decoder.decode(java.nio.ByteBuffer.wrap(head,0,Math.max(n,0)),java.nio.CharBuffer.allocate(8192),false);if(!result.isError()){int controls=0;for(int i=0;i<n;i++)if(head[i]>=0&&head[i]<32&&head[i]!='\n'&&head[i]!='\r'&&head[i]!='\t')controls++;if(controls<Math.max(1,n/20))return "txt";}}catch(Exception ignored){}
  return "bin";
 }
 private void prepareNative()throws Exception {
  libraries=new File(getFilesDir(),"ffmpeg-runtime");File archive=new File(getApplicationInfo().nativeLibraryDir,"libffmpeg.zip.so");File marker=new File(libraries,"ready-"+archive.length());if(marker.exists())return;libraries.mkdirs();
  ZipInputStream z=new ZipInputStream(new FileInputStream(archive));String links="{}";try{ZipEntry e;byte[]b=new byte[65536];while((e=z.getNextEntry())!=null){File dest=new File(libraries,e.getName());if(!dest.getCanonicalPath().startsWith(libraries.getCanonicalPath()+File.separator))throw new IOException("Unsafe archive path");if(e.isDirectory()){dest.mkdirs();continue;}dest.getParentFile().mkdirs();FileOutputStream out=new FileOutputStream(dest);try{int n;while((n=z.read(b))!=-1)out.write(b,0,n);}finally{out.close();}}}finally{z.close();}
  File mappings=new File(libraries,"_links.json");if(mappings.exists()){JSONObject aliases=new JSONObject(readFile(mappings));Iterator<String> it=aliases.keys();while(it.hasNext()){String name=it.next();File dest=new File(libraries,name);String target=aliases.getString(name);if(!new File(dest.getParentFile(),target).getCanonicalPath().startsWith(libraries.getCanonicalPath()+File.separator))throw new IOException("Unsafe library link");if(!dest.exists())Os.symlink(target,dest.getAbsolutePath());}}
  marker.createNewFile();
 }
 private String readFile(File f)throws Exception {FileInputStream in=new FileInputStream(f);try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}finally{in.close();}}
 void check()throws Exception{if(cancelled)throw new InterruptedIOException("Cancelled");}
 String execute(List<String> args)throws Exception {
  check();List<String> command=new ArrayList<String>(args);String executable=command.remove(0);command.add(0,new File(getApplicationInfo().nativeLibraryDir,executable.equals("ffprobe")?"libffprobe.so":"libffmpeg.so").getAbsolutePath());ProcessBuilder pb=new ProcessBuilder(command);pb.redirectErrorStream(true);pb.environment().put("LD_LIBRARY_PATH",new File(libraries,"usr/lib").getAbsolutePath()+":"+getApplicationInfo().nativeLibraryDir);pb.environment().put("HOME",getFilesDir().getAbsolutePath());pb.environment().put("TMPDIR",getCacheDir().getAbsolutePath());process=pb.start();final java.lang.Process active=process;final java.util.concurrent.atomic.AtomicLong lastLine=new java.util.concurrent.atomic.AtomicLong(System.currentTimeMillis());final java.util.concurrent.atomic.AtomicBoolean timedOut=new java.util.concurrent.atomic.AtomicBoolean(false);final Timer watchdog=new Timer(true);watchdog.schedule(new TimerTask(){public void run(){if(cancelled)force(active);else if(System.currentTimeMillis()-lastLine.get()>120000){timedOut.set(true);force(active);}}},250,250);if(cancelled)force(process);try{BufferedReader r=new BufferedReader(new InputStreamReader(process.getInputStream(),"UTF-8"));StringBuilder result=new StringBuilder();String line;
  while((line=r.readLine())!=null){lastLine.set(System.currentTimeMillis());if(result.length()<2*1024*1024)result.append(line).append('\n');if(cancelled)force(process);}int code=process.waitFor();watchdog.cancel();process=null;check();if(timedOut.get())throw new IOException(t("İşlem uzun süre yanıt vermedi; durduruldu.","Kar demeke dirêj bersiv neda; hat rawestandin."));if(code!=0)throw new IOException(result.length()>3000?result.substring(result.length()-3000):result.toString());return result.toString();}finally{watchdog.cancel();process=null;}
 }
 MediaEngine.Info probe(File f)throws Exception {
  // Real files often carry broken tags; ffprobe then prints warnings on stderr, which share
  // this output stream. Keep it quiet and read only the JSON object itself.
  String out=execute(new ArrayList<String>(Arrays.asList("ffprobe","-v","quiet","-protocol_whitelist","file,pipe","-show_format","-show_streams","-of","json",f.getAbsolutePath())));
  int from=out.indexOf('{'),to=out.lastIndexOf('}');if(from<0||to<from)throw new IOException(t("Dosyanın ses/video bilgisi okunamadı.","Agahiyên deng/vîdyoyê yên pelê nehatin xwendin."));
  JSONObject json=new JSONObject(out.substring(from,to+1));MediaEngine.Info i=new MediaEngine.Info();JSONArray streams=json.getJSONArray("streams");for(int n=0;n<streams.length();n++){JSONObject s=streams.getJSONObject(n);if(s.optString("codec_type").equals("audio"))i.audio=true;if(s.optString("codec_type").equals("video")&&(s.optJSONObject("disposition")==null||s.optJSONObject("disposition").optInt("attached_pic")!=1)){i.video=true;i.width=s.optInt("width");i.height=s.optInt("height");String[]rate=s.optString("avg_frame_rate","25/1").split("/");try{i.fps=Double.parseDouble(rate[0])/Double.parseDouble(rate[1]);if(!MediaEngine.finite(i.fps)||i.fps<=0)i.fps=25;}catch(Exception ignored){}}}i.duration=json.getJSONObject("format").optDouble("duration",0);if((!i.video&&!i.audio)||i.duration<=0)throw new IOException(t("Bu dosyanın türü veya süresi belirlenemedi.","Cure an dirêjahiya vê dosyeyê nehat naskirin."));return i;
 }
 private double value(EditText field,double fallback)throws Exception {return field==null||field.getText().toString().trim().length()==0?fallback:MediaEngine.seconds(field.getText().toString());}
 private void startJob(){if(source==null){message(t("Önce dosya seç.","Berê dosyeyek hilbijêre."));return;}if(outputTree==null){message(t("Kaydedilecek klasörü seç.","Peldanka tomarkirinê hilbijêre."));return;}if(!ready&&info!=null){message(t("Yerel motor hazırlanıyor.","Motora herêmî tê amadekirin."));return;}
  final MediaEngine.Job template=new MediaEngine.Job();final String selectedAction=action;final boolean speechSrt=speechOutput!=null&&speechOutput.getSelectedItemPosition()==1;final String format=formats==null?"pdf":formats.getSelectedItem().toString().toLowerCase(Locale.ROOT);final boolean rich=contentMode!=null&&contentMode.getSelectedItemPosition()==1;final int pages;final String speechLang=recognitionLanguage!=null&&recognitionLanguage.getSelectedItemPosition()==1?"en":"tr";final String ocrLang=recognitionLanguage==null?"tur+eng":new String[]{"tur+eng","tur","eng","kmr","ara","fas"}[recognitionLanguage.getSelectedItemPosition()];
  try{template.source=source;template.other=other;template.info=info;template.otherInfo=otherInfo;template.action=action;template.format=action.equals("subtitle")?(subtitleMode!=null&&subtitleMode.getSelectedItemPosition()==1?"soft":"burn"):format;template.start=value(begin,0);template.end=value(end,-1);template.part=value(part,60);template.audioStart=value(audioBegin,0);template.audioEnd=value(audioEnd,-1);if(factor!=null)template.factor=Double.parseDouble(factor.getText().toString().replace(',','.'));template.quality=quality==null?"balanced":quality.getSelectedItemPosition()==1?"high":quality.getSelectedItemPosition()==2?"small":"balanced";pages=info==null&&part!=null?Integer.parseInt(part.getText().toString()):1;if(Arrays.asList("merge","add","replace","subtitle_restore","subtitle").contains(action)&&other==null&&!(action.equals("merge")&&batchEnabled&&files.size()>1))throw new IOException(t("İkinci dosyayı seç.","Dosyeya duyem hilbijêre."));}catch(Exception e){failure(e);return;}
  final List<ListedFile> selectedFiles=batchEnabled&&files.size()>1?new ArrayList<ListedFile>(files):Arrays.asList(new ListedFile(source,display,ext,info));
  busy=true;cancelled=false;controls();progress.setIndeterminate(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);new Thread(new Runnable(){public void run(){int saved=0,failed=0;SpeechEngine speechEngine=new SpeechEngine(MainActivity.this,new SpeechEngine.Host(){public void check()throws Exception{MainActivity.this.check();}public void run(List<String>args)throws Exception{execute(args);}public void progress(double current,double total){message(t("Konuşma yazılıyor: ","Axaftin tê nivîsandin: ")+(int)current+" / "+(int)total+t(" saniye"," çirke"));}},true);try{
   if(selectedAction.equals("merge")&&selectedFiles.size()>1){File work=new File(getCacheDir(),"merge-task-"+System.nanoTime());work.mkdirs();List<Uri>published=new ArrayList<Uri>();try{List<File>paths=new ArrayList<File>();List<MediaEngine.Info>infos=new ArrayList<MediaEngine.Info>();for(ListedFile entry:selectedFiles){check();if((template.info==null&&entry.info==null&&entry.ext.equals("pdf"))||(template.info!=null&&entry.info!=null&&entry.info.video==template.info.video)){paths.add(entry.file);infos.add(entry.info);}else{failed++;log.append(entry.name).append(" — ").append(t("Bu işlem için uygun değil.","Ji bo vî karî ne guncav e.")).append('\n');}}List<File>outputs;if(template.info==null)outputs=Arrays.asList(DocumentEngine.mergeMany(paths,work,new RichDocument.Host(){public void check()throws Exception{MainActivity.this.check();}}));else outputs=new MediaEngine(new MediaEngine.Host(){public void run(List<String>args)throws Exception{execute(args);}public void check()throws Exception{MainActivity.this.check();}},work).mergeMany(paths,infos);saved+=publish(outputs,display,selectedAction,published);}catch(Exception error){for(Uri uri:published)try{DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}throw error;}finally{delete(work);}}
   else for(ListedFile entry:selectedFiles){check();final File source=entry.file;final String ext=entry.ext,display=entry.name;final MediaEngine.Info info=entry.info;final MediaEngine.Job j=MediaEngine.copy(template);j.source=source;j.info=info;File work=new File(getCacheDir(),"task-"+System.nanoTime());work.mkdirs();List<Uri>published=new ArrayList<Uri>();try{
    List<File>outputs=produce(entry,j,selectedAction,format,rich,pages,speechLang,speechSrt,ocrLang,speechEngine,work);
   saved+=publish(outputs,display,selectedAction,published);
   }catch(Exception error){for(Uri uri:published)try{DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}if(cancelled)throw error;failed++;log.append(display).append(" — ");failure(error);}finally{ocr=null;delete(work);}}
   final int count=saved,errors=failed;runOnUiThread(new Runnable(){public void run(){progress.setIndeterminate(false);progress.setProgress(100);String summary=t("İşlem bitti. Kaydedilen: ","Kar qediya. Tomarkirî: ")+count+t(" · Atlanan / hatalı: "," · Derbaskirî / çewt: ")+errors;message(summary);if(details!=null)details.setText(log.toString());new AlertDialog.Builder(MainActivity.this).setTitle(t("İşlem tamamlandı","Kar qediya")).setMessage(summary).setPositiveButton(t("Tamam","Temam"),null).show();}});
  }catch(Exception error){if(cancelled)message(t("İşlem durduruldu. Tamamlanan çıktılar ve orijinaller korunuyor.","Kar hat rawestandin. Encamên qediyayî û pelên resen tên parastin."));else failure(error);}finally{speechEngine.close();ocr=null;finishBusy();}}}).start();
 }
 private boolean supportsEntry(ListedFile file,String action,String format){boolean media=file.info!=null,video=media&&file.info.video,audio=media&&file.info.audio;if(action.equals("subtitle_text"))return file.ext.equals("srt");if(action.equals("subtitle_restore"))return file.ext.equals("txt");if(action.equals("transcribe"))return audio;if(action.equals("ocr"))return file.ext.equals("pdf")||file.ext.equals("image");if(action.equals("convert")){if(file.ext.equals("srt"))return format.equals("txt");if(!media)return !file.ext.equals("image")&&Arrays.asList("pdf","txt","docx","odt","rtf","epub","md","html").contains(format);boolean sound=Arrays.asList("mp3","wav","flac","ogg","opus","m4a","aac","aiff","wma").contains(format);return sound?audio:video&&Arrays.asList("mp4","mkv","webm","mov","avi","mpeg","ts","gif").contains(format);}if(!media)return file.ext.equals("pdf")&&Arrays.asList("split","merge").contains(action);if(Arrays.asList("trim","remove","split","merge","speed").contains(action))return true;if(Arrays.asList("mute_range","volume","fade_in","fade_out").contains(action))return audio;if(Arrays.asList("mute","add","frame","gif","rotate","subtitle").contains(action))return video;return video&&audio&&Arrays.asList("extract","replace").contains(action);}
 private int publish(List<File>outputs,String display,String selectedAction,List<Uri>published)throws Exception{check();Uri parent=DocumentsContract.buildDocumentUriUsingTree(outputTree,DocumentsContract.getTreeDocumentId(outputTree));int count=0;for(File file:outputs){check();String suffix=file.getName().substring(file.getName().lastIndexOf('.')+1);String name=new File(display).getName().replaceFirst("\\.[^.]+$","")+"-"+(selectedAction.equals("convert")?"donusturuldu":selectedAction)+(outputs.size()>1?"-"+(++count):"")+"."+suffix;Uri uri=DocumentsContract.createDocument(getContentResolver(),parent,mime(suffix),uniqueName(parent,name));if(uri==null)throw new IOException("Cannot create output");published.add(uri);OutputStream dst=getContentResolver().openOutputStream(uri);InputStream src=new FileInputStream(file);try{byte[]buffer=new byte[65536];int n;while((n=src.read(buffer))!=-1){check();dst.write(buffer,0,n);}}finally{src.close();dst.close();}}return outputs.size();}

 private String uniqueName(Uri parent,String name)throws Exception {Set<String> names=new HashSet<String>();Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(outputTree,DocumentsContract.getDocumentId(parent));Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null);if(c!=null)try{while(c.moveToNext())names.add(c.getString(0));}finally{c.close();}int dot=name.lastIndexOf('.');String stem=dot<0?name:name.substring(0,dot),suffix=dot<0?"":name.substring(dot),candidate=name;for(int n=1;names.contains(candidate);n++)candidate=stem+" ("+n+")"+suffix;return candidate;}
 private String mime(String ext){if(ext.equals("srt"))return "application/x-subrip";if(ext.equals("mp3"))return "audio/mpeg";if(ext.equals("m4a"))return "audio/mp4";if(ext.equals("mkv"))return "video/x-matroska";if(ext.equals("mov"))return "video/quicktime";if(ext.equals("avi"))return "video/x-msvideo";if(ext.equals("ts"))return "video/mp2t";if(ext.equals("wma"))return "audio/x-ms-wma";if(ext.equals("aiff"))return "audio/x-aiff";if(ext.equals("opus"))return "audio/ogg";if(ext.equals("pdf"))return "application/pdf";if(ext.equals("docx"))return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";if(ext.equals("odt"))return "application/vnd.oasis.opendocument.text";if(ext.equals("epub"))return "application/epub+zip";if(ext.equals("rtf"))return "application/rtf";if(Arrays.asList("txt","md","html").contains(ext))return ext.equals("html")?"text/html":"text/plain";if(Arrays.asList("png","gif").contains(ext))return "image/"+ext;if(Arrays.asList("mp4","webm","mpeg").contains(ext))return "video/"+ext;if(Arrays.asList("wav","flac","ogg","aac").contains(ext))return "audio/"+ext;return "application/octet-stream";}
 private void delete(File f){if(f.isDirectory()){File[]children=f.listFiles();if(children!=null)for(File c:children)delete(c);}f.delete();}
 private void finishBusy(){runOnUiThread(new Runnable(){public void run(){busy=false;controls();progress.setIndeterminate(false);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}});}
 private static void force(java.lang.Process p){try{java.lang.Process.class.getMethod("destroyForcibly").invoke(p);}catch(Exception ignored){p.destroy();}}
 private void cancel(){cancelled=true;if(ocr!=null)ocr.cancel();java.lang.Process p=process;if(p!=null)force(p);message(t("Durduruluyor…","Tê rawestandin…"));}
 void message(final String value){runOnUiThread(new Runnable(){public void run(){if(status!=null)status.setText(value);}});}
 static String imageError(String key,boolean ku){
  if("speech_memory_low".equals(key))return ku?"Ji bo nivîsandina axaftinê amûreke bi 4 GB RAM û bi kêmî 1,5 GB RAM a vala pêwîst e. Sepanên din bigire an amûreke bi RAM a zêdetir bi kar bîne.":"Konuşmayı yazıya dökmek için 4 GB RAM bulunan bir cihaz ve en az 1,5 GB boş RAM gerekiyor. Diğer uygulamaları kapat veya daha fazla RAM bulunan bir cihaz kullan.";
  if("subtitle_invalid".equals(key))return ku?"Formata SRT an demkod ne rast in.":"SRT biçimi veya zaman kodları geçersiz.";
  if("subtitle_line_count".equals(key))return ku?"Hejmara rêzên TXT û SRT divê yek be. Rêzan vala nehêle.":"TXT satır sayısı orijinal SRT ile aynı olmalı. Satırları birleştirme, bölme veya boş bırakma.";
  if("image_reference_unavailable".equals(key))return ku?"Di belgeyê de gihîştina wêneyekê ne pêkan e. Wêneyê di belgeyê de tomar bike û dîsa biceribîne, an Tenê nivîs hilbijêre.":"Belgedeki bir görsele erişilemiyor. Görseli belgeye gömerek yeniden kaydet ya da Yalnızca metin seçeneğini kullan.";
  if("external_image_unavailable".equals(key))return ku?"Wêne ji girêdaneke derve nayê daxistin. Ji bo bikaranîna bê înternetê wêneyê di belgeyê de tomar bike, an Tenê nivîs hilbijêre.":"Dış bağlantıdaki görsel indirilmiyor. Çevrimdışı kullanım için görseli belgeye gömerek kaydet ya da Yalnızca metin seçeneğini kullan.";
  return null;
 }
 private void failure(final Exception e){String detail=imageError(e.getMessage(),ku);final String value=t("İşlem tamamlanamadı: ","Kar nehat temamkirin: ")+(detail==null?e.toString():detail);log.append(value).append('\n');runOnUiThread(new Runnable(){public void run(){message(value);if(details!=null)details.setText(log.toString());}});}
 public void onBackPressed(){if(busy)new AlertDialog.Builder(this).setMessage(t("İşlemi durdurup çıkılsın mı?","Kar were rawestandin û derkeve?" )).setPositiveButton(t("Durdur ve çık","Rawestîne û derkeve"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){cancel();finish();}}).setNegativeButton(t("Devam et","Berdewam bike"),null).show();else super.onBackPressed();}
 protected void onDestroy(){if(isFinishing())cancelled=true;super.onDestroy();}
